define("mod_pptbook/lightbox", ["jquery"], function($) {
    'use strict';

    const SEL_link  = ".pptbook-zoom";
    const SEL_modal = "#pptbook-modal";
    const SEL_img   = "#pptbook-modal-img";
    const SEL_prev  = "#pptbook-modal-prev";
    const SEL_next  = "#pptbook-modal-next";

    let items = [];
    let current = -1;

    function collect() {
        items = [];
        $(SEL_link).each(function() {
            const $a = $(this);
            items.push({
                src: $a.data("full") || $a.attr("href"),
                alt: $a.find("img").attr("alt") || ""
            });
        });
    }

    function show(idx) {
        if (idx < 0 || idx >= items.length) {
            return;
        }
        current = idx;
        $(SEL_img).attr("src", items[idx].src).attr("alt", items[idx].alt || "");
        $(SEL_prev).prop("disabled", current === 0);
        $(SEL_next).prop("disabled", current === items.length - 1);
    }

    function open(idx) {
        if (!items[idx] || !items[idx].src) {
            return;
        }
        show(idx);
        $(SEL_modal).css("display", "flex").attr("aria-hidden", "false");
        $("body").addClass("pptbook-modal-open");
    }

    function close() {
        $(SEL_modal).css("display", "none").attr("aria-hidden", "true");
        $(SEL_img).removeAttr("src");
        $("body").removeClass("pptbook-modal-open");
        current = -1;
    }

    return {
        init: function() {
            $(document).on("click", SEL_link, function(e) {
                e.preventDefault();
                if (!items.length) {
                    collect();
                }
                const idx = $(SEL_link).index(this);
                if (idx >= 0) {
                    open(idx);
                }
            });

            $(document).on("click", SEL_modal, function(e) {
                const id = e.target.id;
                if (id === "pptbook-modal" || id === "pptbook-modal-img") {
                    close();
                }
            });

            $(document).on("click", SEL_prev, function(e) {
                e.stopPropagation();
                show(current - 1);
            });

            $(document).on("click", SEL_next, function(e) {
                e.stopPropagation();
                show(current + 1);
            });

            $(document).on("keyup", function(e) {
                if ($(SEL_modal).css("display") === "none") {
                    return;
                }
                if (e.key === "Escape") {
                    close();
                }
            });
        }
    };
});